package got.client.wildlife; import got.GOTMod; import net.minecraft.client.renderer.entity.*; import net.minecraft.resources.ResourceLocation; import net.minecraft.world.entity.Mob; import java.util.function.Function; public final class GOTScorpionRenderer<T extends Mob> extends MobRenderer<T,GOTScorpionModel<T>>{private final Function<T,String> texture;private final float scale;public GOTScorpionRenderer(EntityRendererProvider.Context c,float shadow,float scale,Function<T,String> tex){super(c,new GOTScorpionModel<>(c.bakeLayer(GOTScorpionLayers.SCORPION)),shadow);this.scale=scale;texture=tex;}public ResourceLocation getTextureLocation(T e){return new ResourceLocation(GOTMod.MOD_ID,texture.apply(e));}protected void scale(T e,com.mojang.blaze3d.vertex.PoseStack p,float f){p.scale(scale,scale,scale);}}
